<script lang="ts">
  import { api, query } from './api';
  import type { Data } from './types';
  import Receipt from './Receipt.svelte';
  export let view: string;
  let error = '', message = '', loading = false, products: Data[] = [], categories: Data[] = [], chosen: string[] = [], periods: Data[] = [], report: Data = {}, member: Data | null = null, memberItems: Data[] = [], invoice: Data | null = null;
  let edit: Data | null = null, search = '', period = '', page = 1, more = false;
  let lastView = '', orderCategory = '', memberPage = 1, memberMore = false;
  const rp = (n: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(n || 0);
  $: if (view !== lastView) { lastView = view; if (typeof window !== 'undefined') load(); }
  async function load(next = false) { loading = true; error = ''; try {
    if (view === 'produk') { const p = next ? page + 1 : 1; const result = await api<Data>('/admin/produk' + query({ q: search, page: p, size: 100 })); products = next ? [...products, ...result.items] : result.items; page = p; more = result.ada_lagi; categories = await api('/admin/kategori'); }
    if (view === 'urut') { categories = await api('/admin/kategori'); const visible = await api<string[]>('/admin/kategori-tampil'); if (visible.length) categories = categories.filter(c => visible.includes(c.id)); if (!orderCategory || !categories.some(c => c.id === orderCategory)) orderCategory = categories[0]?.id || ''; products = []; more = false; if (orderCategory) { for (let p = 1; p <= 10; p++) { const result = await api<Data>('/admin/produk' + query({ kategori: orderCategory, aktif: 'Y', page: p, size: 100 })); products = [...products, ...result.items]; more = result.ada_lagi; if (!more) break; } } }
    if (view === 'kategori') { categories = await api('/admin/kategori'); chosen = await api('/admin/kategori-tampil'); }
    if (view === 'rekap') { const ps = await api<Data>('/admin/periode'); periods = ps.items; if (!period && (ps.sekarang || ps.items[0])) period = String(ps.sekarang || ps.items[0].periode); report = await api('/admin/rekap-anggota' + query({ periode: period })); }
  } catch (e) { error = (e as Error).message; } finally { loading = false; } }
  async function run(f: () => Promise<unknown>, notice = 'Berhasil disimpan.') { error = ''; try { await f(); message = notice; await load(); } catch (e) { error = (e as Error).message; } }
  async function saveProduct() { if (!edit) return; const p = edit; await run(() => api('/admin/produk/' + p.id, { method:'PUT', body: { nama:p.nama, barcode:p.barcode, satuan:p.satuan, kategori_id:p.kategori_id, harga:Number(p.harga), beli:Number(p.beli), aktif:p.aktif } })); if (!error) edit = null; }
  async function upload(e: Event, id: number) { const file = (e.currentTarget as HTMLInputElement).files?.[0]; if (file) await run(() => api('/admin/produk/' + id + '/foto', {method:'PUT',body:file,headers:{'Content-Type':'application/octet-stream'}}), 'Foto disimpan.'); }
  function move(i: number, delta: number) { const j = i + delta; if (j < 0 || j >= products.length) return; [products[i], products[j]] = [products[j], products[i]]; products = [...products]; }
  async function openMember(m: Data, next = false) { try { member = m; const p = next ? memberPage + 1 : 1; const result = await api<Data>('/admin/rekap-anggota/' + encodeURIComponent(m.nik) + '/transaksi' + query({periode:period,page:p,size:100})); memberItems = next ? [...memberItems, ...result.items] : result.items; memberPage = p; memberMore = result.ada_lagi; } catch(e) { error = (e as Error).message; } }
  async function showInvoice(no: string) { try { invoice = await api('/admin/faktur/' + encodeURIComponent(no)); } catch(e) { error = (e as Error).message; } }
</script>
{#if error}<div class="error" role="alert">{error}</div>{/if}{#if message}<div class="notice">{message}</div>{/if}{#if loading}<p class="muted">Memuat data…</p>{/if}
<section class="panel"><div class="section-heading"><div><p class="eyebrow">ADMINISTRASI</p><h2>{view === 'produk' ? 'Katalog produk' : view === 'kategori' ? 'Kategori tampil' : view === 'urut' ? 'Urutan produk' : 'Rekap anggota'}</h2></div></div>
{#if view === 'produk' || view === 'urut'}{#if view === 'produk'}<form class="search" on:submit|preventDefault={() => load()}><input bind:value={search} placeholder="Cari produk"/><button>Cari</button></form>{:else}<label>Kategori<select bind:value={orderCategory} on:change={() => load()}>{#each categories as c}<option value={c.id}>{c.nama}</option>{/each}</select></label><p class="muted">Urutkan seluruh produk aktif dalam kategori ini.</p>{#if more}<div class="error">Kategori memiliki lebih dari 1.000 produk dan tidak dapat diurutkan di sini.</div>{/if}{/if}{#each products as p, i}<div class="admin-row"><div><strong>{p.nama}</strong><small>{p.kode} · {p.kategori} · {rp(p.harga)} · {p.aktif ? 'Aktif' : 'Nonaktif'}</small></div><div class="actions">{#if view === 'produk'}<button on:click={() => edit = {...p}}>Ubah</button>{:else}<button on:click={() => move(i,-1)} disabled={i === 0}>↑</button><button on:click={() => move(i,1)} disabled={i === products.length-1}>↓</button>{/if}</div></div>{/each}{#if more && view === 'produk'}<button class="secondary" on:click={() => load(true)}>Muat lebih banyak</button>{/if}{#if view === 'urut' && products.length && !more}<button class="primary" on:click={() => run(() => api('/admin/produk-urut',{method:'PUT',body:{produk_ids:products.map(p => p.id)}}))}>Simpan urutan</button>{/if}
{:else if view === 'kategori'}<p class="muted">Jika tidak ada kategori yang dipilih, semua kategori ditampilkan.</p>{#each categories as c}<label class="check"><input type="checkbox" value={c.id} bind:group={chosen}/>{c.nama}</label>{/each}<button class="primary" on:click={() => run(() => api('/admin/kategori-tampil',{method:'PUT',body:{kategori_ids:chosen}}))}>Simpan kategori</button>
{:else if view === 'rekap'}<label>Periode<select bind:value={period} on:change={() => load()}>{#each periods as p}<option value={String(p.periode)}>{p.periode} · {p.dari} – {p.sampai}</option>{/each}</select></label><p>Total: <strong>{rp(report.total)}</strong> · {report.jumlah_transaksi || 0} transaksi</p>{#each report.items || [] as m}<button class="list-button horizontal" on:click={() => openMember(m)}><span><strong>{m.nama}</strong><small>{m.nik} · {m.unit} · {m.jumlah} transaksi</small></span><strong>{rp(m.total)} →</strong></button>{/each}{/if}</section>
{#if edit}<div class="overlay"><section class="modal"><div class="row"><h2>Ubah produk</h2><button class="icon" on:click={() => edit = null}>×</button></div>{#if error}<div class="error">{error}</div>{/if}<form on:submit|preventDefault={saveProduct}><label>Nama<input bind:value={edit.nama} required/></label><label>Barcode<input bind:value={edit.barcode}/></label><label>Satuan<input bind:value={edit.satuan} required/></label><label>Kategori<select bind:value={edit.kategori_id}>{#each categories as c}<option value={c.id}>{c.nama}</option>{/each}</select></label><label>Harga jual<input type="number" bind:value={edit.harga} min="0" required/></label><label>Harga beli<input type="number" bind:value={edit.beli} min="0" required/></label><label class="check"><input type="checkbox" bind:checked={edit.aktif}/> Aktif</label><button class="primary">Simpan</button></form><label>Foto produk (JPEG/PNG, maks. 1 MB)<input type="file" accept="image/jpeg,image/png" on:change={(e) => upload(e, edit!.id)}/></label><button on:click={() => run(() => api('/admin/produk/' + edit!.id + '/foto',{method:'DELETE'}),'Foto dihapus.')}>Hapus foto</button></section></div>{/if}
{#if member}<div class="overlay"><section class="modal"><div class="row"><h2>{member.nama}</h2><button class="icon" on:click={() => member = null}>×</button></div><p>{member.nik} · {rp(member.total)}</p>{#each memberItems as t}<button class="list-button horizontal" on:click={() => showInvoice(t.no_transaksi)}><span>{t.no_transaksi}<small>{t.tanggal}</small></span><strong>{rp(t.total)} →</strong></button>{:else}<p class="empty">Tidak ada transaksi.</p>{/each}{#if memberMore}<button class="secondary wide" on:click={() => openMember(member!, true)}>Muat lebih banyak</button>{/if}</section></div>{/if}
{#if invoice}<Receipt {invoice} close={() => invoice = null}/>{/if}
